import React, { useMemo, useState } from 'react';
import {
  Ellipsis,
  FileText,
  Heart,
  Image,
  List,
  MessageCircle,
  Repeat2,
  UsersRound
} from 'lucide-react';
import styles from './Posts.module.scss';
import { FEED_WEIGHTS } from '../../recommendation/feedConfig';
import {
  buildSpecificQualificationKey,
  getSavedCirclePreferences,
  PERIODS,
  QUALIFICATION_GROUPS
} from './categoryFilters';

const EMPTY_FILTERS = {
  periods: [],
  generalQualifications: [],
  specificQualifications: []
};

const POSTS = [
  {
    id: 1,
    author: 'Charles Deo',
    handle: '@Charles_deo',
    time: '15mins ago',
    category: 'История',
    title: 'New Blazer out here... $500!!!!!',
    text: 'Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry standard text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.',
    likes: 1498,
    shares: 1498,
    comments: 50,
    isFriend: true,
    isNew: true,
    periodizations: ['Античност'],
    qualifications: ['История', 'Културна история', 'Философия', 'История на идеите']
  },
  {
    id: 2,
    author: 'Maria Gonzalez',
    handle: '@maria.gonzalez',
    time: '28mins ago',
    category: 'Философия',
    title: 'Защо идеите имат история',
    text: 'Когато промениш контекста, променяш и значението на тезите. Историята на идеите не е архив, а жива среда за дебат, в която понятията сменят функцията си.',
    likes: 938,
    shares: 332,
    comments: 42,
    isFriend: true,
    isNew: false,
    periodizations: ['Ренесанс'],
    qualifications: ['Философия', 'История на идеите', 'Етика']
  },
  {
    id: 3,
    author: 'Liam O\'Brien',
    handle: '@liam.obrien',
    time: '43mins ago',
    category: 'Изкуства',
    title: 'Кино езикът на авангарда',
    text: 'Визуалният ритъм и монтажът променят не само формата, но и начина, по който мислим сюжета. Авангардът работи със зрителското внимание като материал.',
    likes: 410,
    shares: 121,
    comments: 18,
    isFriend: false,
    isNew: true,
    periodizations: ['Авангард'],
    qualifications: ['Изкуства', 'Визуални изкуства', 'Кино']
  },
  {
    id: 4,
    author: 'Sofia Rossi',
    handle: '@sofia.rossi',
    time: '1h ago',
    category: 'Литература',
    title: 'Етика в публичния разговор',
    text: 'Няма плурализъм без общи правила за аргумент. Свободата на мнение работи добре тогава, когато се комбинира с отговорност към фактите.',
    likes: 216,
    shares: 77,
    comments: 30,
    isFriend: false,
    isNew: false,
    periodizations: ['Съвременност'],
    qualifications: ['Литература', 'Есеистика', 'Етика']
  },
  {
    id: 5,
    author: 'Nikolay Petrov',
    handle: '@nikolay.petrov',
    time: '2h ago',
    category: 'Социология',
    title: 'Политическата памет в съвременната Европа',
    text: 'Преразказването на миналото винаги е политическо решение — чрез него избираме кой е герой и кой е спомоенно забравен.',
    likes: 742,
    shares: 211,
    comments: 28,
    isFriend: true,
    isNew: true,
    periodizations: ['Просвещение'],
    qualifications: ['История', 'Политическа история', 'Политология']
  },
  {
    id: 6,
    author: 'Elena Markova',
    handle: '@elena.markova',
    time: '4h ago',
    category: 'Изкуства',
    title: 'Как музиката променя усещането за време',
    text: 'В музикалния дискурс ритъмът не е само метрика, а социална позиция и памет за културни практики.',
    likes: 589,
    shares: 101,
    comments: 19,
    isFriend: false,
    isNew: false,
    periodizations: ['Модернизъм'],
    qualifications: ['Изкуства', 'Музика', 'Естетика']
  }
];

const FRIENDS = [
  { name: 'Eddie Lobanovskiy', email: 'lobanovskiy@gmail.com' },
  { name: 'Alexey Stave', email: 'alexeyts@gmail.com' },
  { name: 'Anton Tkacheve', email: 'tkacheveanton@gmail.com' },
  { name: 'Maria Gonzalez', email: 'maria.gonzalez@email.com' },
  { name: 'Jin Park', email: 'jin.park@email.com' },
  { name: 'Liam O\'Brien', email: 'liam.obrien@email.com' },
  { name: 'Aisha Khan', email: 'aisha.khan@email.com' },
  { name: 'Ravi Patel', email: 'ravi.patel@email.com' },
  { name: 'Sofia Rossi', email: 'sofia.rossi@email.com' },
  { name: 'David Kim', email: 'david.kim@email.com' }
];

const takeUnique = (source, count, selectedIds) => {
  const result = [];
  for (const item of source) {
    if (result.length >= count) break;
    if (selectedIds.has(item.id)) continue;
    selectedIds.add(item.id);
    result.push(item);
  }
  return result;
};

const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5);

const getInitialFilterState = () => {
  try {
    const saved = getSavedCirclePreferences();
    return saved || EMPTY_FILTERS;
  } catch (error) {
    return EMPTY_FILTERS;
  }
};

export default function Posts({ onNavigate }) {
  const [searchText, setSearchText] = useState('');
  const initialFilters = useMemo(() => getInitialFilterState(), []);
  const [selectedPeriods, setSelectedPeriods] = useState(initialFilters.periods);
  const [selectedGeneralQualifications, setSelectedGeneralQualifications] = useState(initialFilters.generalQualifications);
  const [selectedSpecificQualifications, setSelectedSpecificQualifications] = useState(initialFilters.specificQualifications);

  const hasActiveFilters = selectedPeriods.length > 0 || selectedGeneralQualifications.length > 0 || selectedSpecificQualifications.length > 0;

  const togglePeriod = (periodName) => {
    setSelectedPeriods((prev) => (
      prev.includes(periodName)
        ? prev.filter((item) => item !== periodName)
        : [...prev, periodName]
    ));
  };

  const toggleGeneralQualification = (groupName) => {
    setSelectedGeneralQualifications((prev) => {
      const isSelected = prev.includes(groupName);
      if (!isSelected) {
        return [...prev, groupName];
      }

      setSelectedSpecificQualifications((specificPrev) => (
        specificPrev.filter((item) => !item.startsWith(`${groupName}::`))
      ));
      return prev.filter((item) => item !== groupName);
    });
  };

  const toggleSpecificQualification = (groupName, itemName) => {
    const key = buildSpecificQualificationKey(groupName, itemName);

    setSelectedSpecificQualifications((prev) => (
      prev.includes(key) ? prev.filter((item) => item !== key) : [...prev, key]
    ));

    setSelectedGeneralQualifications((prev) => (
      prev.includes(groupName) ? prev : [...prev, groupName]
    ));
  };

  const clearFilters = () => {
    setSelectedPeriods([]);
    setSelectedGeneralQualifications([]);
    setSelectedSpecificQualifications([]);
  };

  const displayedPosts = useMemo(() => {
    const q = searchText.trim().toLowerCase();
    const hasAnyQualificationFilter = selectedGeneralQualifications.length > 0 || selectedSpecificQualifications.length > 0;

    const base = POSTS.filter((post) => {
      const matchesQuery = q.length === 0
        || post.title.toLowerCase().includes(q)
        || post.text.toLowerCase().includes(q)
        || post.author.toLowerCase().includes(q)
        || post.category.toLowerCase().includes(q);

      if (!matchesQuery) {
        return false;
      }

      const postQualificationSet = new Set(post.qualifications || []);
      const hasPeriod = !selectedPeriods.length || (post.periodizations || []).some((period) => selectedPeriods.includes(period));

      const hasQualification = !hasAnyQualificationFilter
        ? true
        : selectedGeneralQualifications.some((groupName) => postQualificationSet.has(groupName))
          || selectedSpecificQualifications.some((key) => postQualificationSet.has(key.split('::')[1]));

      return hasPeriod && hasQualification;
    });

    const interestPool = shuffle(base.filter((post) => post.isFriend));
    const freshPool = shuffle(base.filter((post) => post.isNew));
    const randomPool = shuffle(base);

    const total = Math.min(base.length, 8);
    const interestCount = Math.round(total * (FEED_WEIGHTS.interest / 100));
    const freshCount = Math.round(total * (FEED_WEIGHTS.fresh / 100));
    const randomCount = Math.max(0, total - interestCount - freshCount);

    const selectedIds = new Set();
    const fromInterest = takeUnique(interestPool, interestCount, selectedIds);
    const fromFresh = takeUnique(freshPool, freshCount, selectedIds);
    const fromRandom = takeUnique(randomPool, randomCount, selectedIds);

    return [...fromInterest, ...fromFresh, ...fromRandom];
  }, [searchText, selectedPeriods, selectedGeneralQualifications, selectedSpecificQualifications]);

  return (
    <div className={styles.page}>
      <main className={styles.shell}>
        <section className={styles.board}>
          <aside className={styles.leftPanel}>
            <div className={styles.categories}>
              <p>Филтри</p>
              <div className={styles.filterHeader}>
                <strong>Периодизация</strong>
                {hasActiveFilters ? (
                  <button type="button" className={styles.clearButton} onClick={clearFilters}>
                    Изчисти
                  </button>
                ) : null}
              </div>
              <div className={styles.filterBlock}>
                {PERIODS.map((period) => (
                  <label key={period} className={styles.filterItem}>
                    <input
                      type="checkbox"
                      checked={selectedPeriods.includes(period)}
                      onChange={() => togglePeriod(period)}
                    />
                    <span>{period}</span>
                  </label>
                ))}
              </div>

              <div className={styles.filterHeader}>
                <strong>Квалификация</strong>
              </div>
              <div className={styles.filterBlock}>
                {QUALIFICATION_GROUPS.map((group) => (
                  <label key={group.name} className={styles.filterItem}>
                    <input
                      type="checkbox"
                      checked={selectedGeneralQualifications.includes(group.name)}
                      onChange={() => toggleGeneralQualification(group.name)}
                    />
                    <span>{group.name}</span>
                  </label>
                ))}
              </div>

              {QUALIFICATION_GROUPS.map((group) => (
                <div key={group.name} className={styles.subGroup}>
                  <h3>{group.name}</h3>
                  <div className={styles.filterBlock}>
                    {group.items.map((item) => (
                      <label key={`${group.name}-${item}`} className={styles.filterItem}>
                        <input
                          type="checkbox"
                          checked={selectedSpecificQualifications.includes(buildSpecificQualificationKey(group.name, item))}
                          onChange={() => toggleSpecificQualification(group.name, item)}
                        />
                        <span>{item}</span>
                      </label>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>

          <section className={styles.feedColumn}>
            <article className={styles.createPostCard}>
              <div className={styles.avatar} aria-hidden="true">👨🏽</div>
              <div className={styles.createBody}>
                <input
                  type="text"
                  value={searchText}
                  onChange={(event) => setSearchText(event.target.value)}
                  placeholder="What's happening ?"
                />
                <div className={styles.createActions}>
                  <div className={styles.createIcons}>
                    <Image size={18} />
                    <List size={18} />
                    <MessageCircle size={18} />
                    <FileText size={18} />
                  </div>
                  <button type="button">Post</button>
                </div>
              </div>
            </article>

            {displayedPosts.length > 0 ? (
              displayedPosts.map((post) => (
                <article key={post.id} className={styles.postCard}>
                  <header className={styles.postHeader}>
                    <div className={styles.avatar} aria-hidden="true">👨🏽</div>
                    <div className={styles.postMeta}>
                      <div className={styles.authorRow}>
                        <strong>{post.author}</strong>
                        <UsersRound size={18} />
                      </div>
                      <span>{post.time}</span>
                    </div>
                    <button type="button" className={styles.moreBtn}>
                      <Ellipsis size={18} />
                    </button>
                  </header>

                  <p className={styles.postTitle}>{post.title}</p>
                  <p className={styles.postSubtitle}>
                    {post.category}
                    {post.periodizations?.[0] ? ` • ${post.periodizations[0]}` : ''}
                  </p>
                  <p className={styles.postText}>{post.text}</p>

                  <footer className={styles.postFooter}>
                    <div>
                      <Heart size={19} /> {post.likes.toLocaleString()}
                    </div>
                    <div>
                      <Repeat2 size={19} /> {post.shares.toLocaleString()}
                    </div>
                    <div>
                      <MessageCircle size={19} /> {post.comments}
                    </div>
                  </footer>

                  <button type="button" className={styles.seeMore}>See more</button>
                </article>
              ))
            ) : (
              <article className={styles.emptyState}>
                <p>Няма публикации за избраните филтри.</p>
              </article>
            )}
          </section>

          <aside className={styles.rightPanel}>
            <article className={styles.profileCard}>
              <div className={styles.avatar} aria-hidden="true">👨🏽</div>
              <div>
                <strong>Charles Deo</strong>
                <p>@Charles_deo</p>
              </div>
              <button type="button" className={styles.moreBtn}><Ellipsis size={18} /></button>
            </article>

            <article className={styles.friendsCard}>
              <h3>Friends</h3>
              <ul>
                {FRIENDS.map((friend) => (
                  <li key={friend.email}>
                    <div className={styles.friendAvatar} aria-hidden="true">👤</div>
                    <div>
                      <strong>{friend.name}</strong>
                      <p>{friend.email}</p>
                    </div>
                  </li>
                ))}
              </ul>
            </article>
          </aside>
        </section>
      </main>
    </div>
  );
}
